[InitializeOnLoad] public static class TempEvansFinalSetup {
const string R="Assets/_Project/Configs/Reactions/Hangar/", M="Assets/_Project/Configs/Memories/Hangar/", A="Assets/_Project/Art/Memories/Hangar/EvansFinalMemory/";
