static void Set(UnityEngine.Object o,string k,object v){var s=new SerializedObject(o);var p=s.FindProperty(k);if(p==null)throw new Exception(k);if(v is string z)p.stringValue=z;else if(v is bool b)p.boolValue=b;else if(v is int i)p.intValue=i;else if(v is float f)p.floatValue=f;else p.objectReferenceValue=v as UnityEngine.Object;s.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}
static T Add<T>(NodeGraph g) where T:Node {var n=g.AddNode<T>();EditorUtility.SetDirty(g);AssetDatabase.AddObjectToAsset(n,g);n.position=new Vector2((g.nodes.Count-1)*350,0);EditorUtility.SetDirty(n);return n;}
static void Link(Node a,Node b){a.GetOutputPort("next").Connect(b.GetInputPort("previous"));EditorUtility.SetDirty(a);EditorUtility.SetDirty(b);}
static T Create<T>(string path) where T:ScriptableObject {if(File.Exists(path))throw new Exception("Already exists "+path);var a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,path);return a;}
static void Binding(ReactionInteractable i,string[] keys,GameObject[] objects){var s=new SerializedObject(i);var p=s.FindProperty("objectBindings");p.arraySize=keys.Length;for(int j=0;j<keys.Length;j++){p.GetArrayElementAtIndex(j).FindPropertyRelative("key").stringValue=keys[j];p.GetArrayElementAtIndex(j).FindPropertyRelative("target").objectReferenceValue=objects[j];}s.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(i);PrefabUtility.RecordPrefabInstancePropertyModifications(i);}
static void Keys(ReactionGraph g,params string[] keys){var s=new SerializedObject(g);var p=s.FindProperty("objectKeys");p.arraySize=keys.Length;for(int j=0;j<keys.Length;j++)p.GetArrayElementAtIndex(j).stringValue=keys[j];s.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(g);}
static ReactionNode Action(ReactionGraph g,ReactionKind k){var n=Add<ReactionNode>(g);Set(n,"kind",(int)k);return n;}
static void Run(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists("Temp/EvansFinalImages.ready"))return;EditorApplication.update-=Run;if(File.Exists("Temp/EvansFinalSetup.done"))return;try{File.WriteAllText("Temp/EvansFinalSetup.done","STARTED");if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Playing");var scene=SceneManager.GetSceneByPath("Assets/_Project/Locations/Hangar.unity");if(!scene.isLoaded)throw new Exception("Scene not loaded");EditorSceneManager.SaveScene(scene,"Temp/HangarBeforeEvansFinal.unity",true);File.Copy(R+"Evans_FourthInteraction.asset","Temp/EvansFourthBeforeFinal.asset",true);var all=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).ToArray();var fourth=all.Single(x=>x.name=="Четвёртый манекен мистера Эванса — у автомобиля").gameObject;var truck=all.Single(x=>x.name=="Hangar Truck 02");if(!truck.GetComponentsInChildren<Transform>(true).Any(x=>x.name.Contains("Sticker")))throw new Exception("Expected green truck with sticker");
AssetDatabase.StartAssetEditing();try{
var memory=Create<MemoryGraph>(M+"EvansFinalMemory.asset");Set(memory,"displayTitle","Мистер Эванс. Сынок");Node previous=Add<MemoryStartNode>(memory);
string[] lines={"Алекс: Но ведь, если вы реализуете трак через аукцион, - можете получить намного больше.","Эванс: Да. Мог бы. Но...","Эванс: Пенсионные накопления у меня есть. Дом есть. Возраст такой, что ни любовницы ни новой жены не потяну. Сын давно умер.","Эванс: Если не помогу тебе встать на ноги... Выходит, когда называл тебя \"сынок\" - воздух сотрясал. А не хотелось бы мне, в моем возрасте, быть просто трепливым стариканом.","Алекс: Спасибо, мистер Эванс. Я это правда ценю. Только мне нужно обсудить это с Беном. Без него такое решение я принять не могу.","Эванс: Конечно. Обсудите все толком. Но сильно не копайтесь. Время бежит."};float[] times={9,4,13,17,13,8};for(int j=0;j<6;j++){var frame=Add<MemoryFrameNode>(memory);var image=AssetDatabase.LoadAssetAtPath<Texture2D>(A+"EvansFinalMemory-"+(j+1).ToString("00")+".png");if(!image)throw new Exception("Missing frame "+j);Set(frame,"image",image);Set(frame,"text",lines[j]);Set(frame,"displayDuration",times[j]);Link(previous,frame);previous=frame;}Link(previous,Add<MemoryEndNode>(memory));
var fg=Create<ReactionGraph>(R+"Evans_FifthInteraction.asset");var fs=Add<ReactionStartNode>(fg);Set(fs,"runOnce",true);var fm=Action(fg,ReactionKind.Memory);Set(fm,"memoryGraph",memory);Set(fm,"memoryId","hangar_evans_final");Link(fs,fm);
var fifth=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LevelDesign/Prefabs/Персонажи/Люди/MrEvans_Mannequin.prefab"),scene);fifth.name="Пятый манекен мистера Эванса — у зелёного трака";fifth.transform.localScale=fourth.transform.lossyScale;fifth.transform.position=new Vector3(190.5f,4.22f,310.25f);var facing=fifth.transform.position-truck.position;facing.y=0;fifth.transform.rotation=Quaternion.LookRotation(facing);var ft=fifth.GetComponent<ObjectStateTracker>();if(!ft)ft=fifth.AddComponent<ObjectStateTracker>();Set(ft,"persistentId","hangar.mannequin.evans.fifth");Set(ft,"initiallyActive",false);var fi=fifth.GetComponent<ReactionInteractable>();if(!fi)fi=fifth.AddComponent<ReactionInteractable>();fi.Configure(fg,"Мистер Эванс");EditorUtility.SetDirty(fi);var fc=fifth.GetComponent<CapsuleCollider>();if(!fc)fc=fifth.AddComponent<CapsuleCollider>();var tc=fourth.GetComponent<CapsuleCollider>();fc.center=tc.center;fc.height=tc.height;fc.radius=tc.radius;fifth.SetActive(true);PrefabUtility.RecordPrefabInstancePropertyModifications(fifth.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(ft);PrefabUtility.RecordPrefabInstancePropertyModifications(fi);
var fourthGraph=AssetDatabase.LoadAssetAtPath<ReactionGraph>(R+"Evans_FourthInteraction.asset");var mn=fourthGraph.nodes.OfType<ReactionNode>().Single(x=>x.Kind==ReactionKind.Memory);if(mn.GetOutputPort("next").IsConnected)throw new Exception("Unexpected existing continuation");var hide=Action(fourthGraph,ReactionKind.ObjectActivity);Set(hide,"objectKey","EvansFourth");Set(hide,"active",false);Set(hide,"revealDuration",0f);var show=Action(fourthGraph,ReactionKind.ObjectActivity);Set(show,"objectKey","EvansFifth");Set(show,"active",true);Set(show,"revealDuration",0f);Link(mn,hide);Link(hide,show);Keys(fourthGraph,"EvansFourth","EvansFifth");Binding(fourth.GetComponent<ReactionInteractable>(),new[]{"EvansFourth","EvansFifth"},new[]{fourth,fifth});
var catalog=AssetDatabase.LoadAssetAtPath<MemoryCatalog>("Assets/_Project/Resources/MemoriesComicCatalog.asset");catalog.entries=catalog.entries.Concat(new[]{new MemoryCatalog.Entry{key=AssetDatabase.AssetPathToGUID(M+"EvansFinalMemory.asset"),graph=memory}}).ToArray();EditorUtility.SetDirty(catalog);if(!memory.TryGetSequence(out _,out var error))throw new Exception(error);foreach(var g in new[]{fg,fourthGraph})if(!g.TryGetSequence(out _,out error))throw new Exception(g.name+error);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Temp/EvansFinalSetup.done","SUCCESS 6 frames, instant fourth->fifth, prompt, tracker, catalog");
}finally{AssetDatabase.StopAssetEditing();}
}catch(Exception e){File.WriteAllText("Temp/EvansFinalSetup.done",e.ToString());Debug.LogException(e);}}
}